--
-- Name: caller_owns_company_referred_to(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_owns_company_referred_to(p_accountant_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from companies
    where owner_user_id = auth.uid() and referred_by_accountant_id = p_accountant_id
  );
$$;


--
-- Name: compute_billing_usage(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_billing_usage(p_company_id uuid, p_from date, p_to date) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select
    coalesce((
      select count(distinct invoice_number) from invoice_vat_lines
      where company_id = p_company_id and direction = 'OUTBOUND'
        and issue_date >= p_from and issue_date <= p_to
    ), 0)
    +
    coalesce((
      select count(distinct invoice_number) from invoice_vat_lines
      where company_id = p_company_id and direction = 'INBOUND'
        and issue_date >= p_from and issue_date <= p_to
    ), 0)
    +
    coalesce((
      select count(distinct (ap_number, date_trunc('day', transaction_at))) from opg_receipt_items
      where company_id = p_company_id
        and transaction_at >= p_from and transaction_at < (p_to + 1)
    ), 0)
$$;


--
-- Name: link_company_to_accountant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_company_to_accountant(p_company_id uuid, p_referral_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_accountant_id uuid;
begin
  if not exists (select 1 from companies where id = p_company_id and owner_user_id = auth.uid()) then
    raise exception 'Nincs jogosultságod ehhez a céghez.';
  end if;

  select id into v_accountant_id from accountants where referral_code ilike p_referral_code limit 1;

  if v_accountant_id is null then
    return false;
  end if;

  update companies set referred_by_accountant_id = v_accountant_id where id = p_company_id;
  return true;
end;
$$;


--
-- Name: lookup_accountant_name_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_accountant_name_by_code(p_referral_code text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select name from accountants where referral_code ilike p_referral_code limit 1;
$$;


--
-- Name: registering_user_matches(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registering_user_matches(p_user_id uuid, p_email text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from auth.users u where u.id = p_user_id and lower(u.email) = lower(p_email)
  );
$$;


